<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Mini Spreadsheet</title>
<style>
  body { margin: 0; font-family: sans-serif; background-color: #f5f5f5; }

  .app-container { 
    min-width: 620px; /* meets >=600 width */
    min-height: 450px; /* meets >=400 height (including controls) */
    padding: 10px;
    display: flex;
    flex-direction: column;
    box-sizing: border-box;
    background-color: white;
    margin: 20px auto;
  }

  #grid-area { overflow-x: auto; min-width: max-content; margin-bottom: 15px; padding: 4px;}

  #spreadsheet-grid { 
    display: grid;
    gap: 0; /* borders handled by items */
    border-collapse: collapse;
    background-color: grey;
    min-width: fit-content;
  }

  .cell-input, .header-cell, .row-header { 
    padding: 4px; text-align: center; font-size: 13px; box-sizing: border-box;
  }

  /* Grid structure */
  #spreadsheet-grid {
      grid-template-columns: 50px repeat(10, 60px); /* Row header + 10 cols */
  }

  .header-cell { background-color: #e8e8e8; font-weight: bold; border-bottom: solid grey; display: flex; align-items: center; justify-content: center;}
  .row-header { background-color: #e8e8e8; font-weight: bold; border-right: solid grey; display: flex; align-items: center; justify-content: center;}

  .cell-input { 
    width: calc(100% - 2px); height: 35px; text-align: right; padding-right: 4px; margin-top: 4.8%;
    border: none; outline: none; background-color: white; font-family: inherit; cursor: cell;
  }

  /* Top headers */
  #col-headers { display: contents; grid-column: 2 / span 10;}

  .controls { margin-top: auto; padding-top: 15px; border-top: 1px solid grey; display: flex; gap: 10px;}

  button, textarea { font-size: 14px; }
  #csv-output { width: 280px; height: 60px; resize: vertical; margin-left: auto; }

</style>
</head>
<body>
<div class="app-container">
    <div id="grid-area">
        <!-- Grid generated by JS -->
        <table style="border-collapse: collapse;"> 
            <thead><tr></tr></thead>
            <tbody id="grid-body"></tbody>
        </table>
    </div>

    <div class="controls">
        <button id="export">Export CSV</button>
        <textarea id="csv-output" placeholder="CSV will appear here..."></textarea>
    </div>
</div>

<script>
(function() {
  // Configuration
  const COLS = ['A','B','C','D','E','F','G','H','I','J'];
  const ROWS = Array.from({length:10}, (_,i)=>i+1);

  // Global State Map: key="ColRow" -> {raw, computed}
  const stateMap = {}; 
  let activeStack = [];

  // Initialize grid and event handlers
  function initGrid() {
    const tbody = document.getElementById('grid-body');

    // Create header row (col letters)
    const theadRow = document.createElement('tr');
    // Top-left empty corner
    const thCorner = document.createElement('th'); 
    theadRow.appendChild(thCorner);
    for(let col of COLS) {
        const th = document.createElement('th');
        th.className = 'header-cell';
        th.textContent = col;
        theadRow.appendChild(th);
    }

    // Create row headers and cells
    for(let row=1; row<=10; row++) {
        const tr = document.createElement('tr');

        // Row Header (left)
        const rh = document.createElement('td');
        rh.className = 'row-header';
        rh.textContent = row;
        // Make it a grid cell? In table, cells are td. 
        // But we want inputs inside to be structured for CSS Grid if used differently...
        // Let's use DIVs with absolute positioning or just keep simple Table layout as valid grid structure.

        tr.appendChild(rh);

        for(let col of COLS) {
            const id = `cell-${col}${row}`;
            const input = document.createElement('input');
            input.type = 'text';
            input.id = id;
            // Basic styling applied via class or inline? Use CSS classes.
            input.className = 'cell-input';

            // Events for commit/edit mode logic
            input.addEventListener('focus', function() {
                if(this.value !== stateMap[this.id]?.computed) {
                   this.value = stateMap[this.id] ? stateMap[this.id].raw : ""; 
                }
                selectAllOnFocus(input);
            });

            input.addEventListener('blur', commitInput.bind(null, id));
            input.addEventListener('keydown', function(e) {
               if(e.key === 'Enter') { this.blur(); } // Commit on Enter
            });

            tr.appendChild(input);
        }
        tbody.appendChild(tr);
    }

    // Populate initial state for all cells (empty strings)
    generateStateMap();
  }

  function selectAllOnFocus(el) { el.select(); }

  function generateStateMap() {
      for(let col of COLS) {
          for(let row=1; row<=10; row++) {
              stateMap[`${col}${row}`] = { raw: "", computed: "" };
          }
      }
  }

  // --- Core Logic ---

  function commitInput(id) {
     const inputEl = document.getElementById(id);
     if(inputEl.value !== stateMap[id].raw && inputEl.tagName === 'INPUT') {
         stateMap[id].raw = inputEl.value;
         recalcAll();
         updateDisplayForCell(stateMap, id); // Update UI after commit (shows result)
     } else {
         // If user cancelled edit? Just revert to current computed value or raw if active.
         const val = stateMap[id] ? stateMap[id].computed : "";
         inputEl.value = val;
     }
  }

  function updateDisplayForCell(state, key) {
      const el = document.getElementById(key);
      if(!el) return;
      // If currently focused and being edited, keep raw? 
      // Usually display computed when not editing.
      if(document.activeElement !== el || !state[key]) {
          el.value = state[key] ? String(state[key].computed) : "";
      } else if (!document.body.contains(el)) {
        // lost focus but still active element in DOM? 
        // Just let blur handler handle it.
      }
  }

  function recalcAll() {
     // Reset stack for a fresh calculation run
     activeStack = [];

     // Clear computed values to force recompute all (or keep stateMap and compute lazily)
     const keys = generateCellKeys();

     // We'll iterate over all cells ensuring each is evaluated. 
     // This triggers full dependency resolution.
     for(let key of keys) {
         ensureComputed(key);
     }

     // Update UI inputs to reflect computed values (unless editing active input)
     // Note: If user was typing in some cell, it might have been updated already by commit logic? 
     // But recalcAll is triggered after edit. The changed cell's raw text was set before call or inside.

     keys.forEach(key => {
        updateDisplayForCell(stateMap, key);
     });
  }

  function ensureComputed(k) {
      const result = calc(k);
      if(result !== undefined && !stateMap[k]) stateMap[k] = {}; // Init if missing (shouldn't happen)

      // If result is not a number or finite, mark as error string.
      let displayVal;
      try {
         // We only set computed if calculation succeeded and produced valid output for formula cells?
         // Actually we need to store whatever the calculated/evaluated value should be displayed as.
         // If it's part of a cycle -> #CYCLE
         // If error in op -> #ERR

         displayVal = result;
      } catch(e) {
          displayVal = "#ERR";
      }

      stateMap[k].computed = String(displayVal); 
  }

  function calc(k) {
     if (activeStack.includes(k)) {
        // Cycle detected involving k and nodes from index of k in activeStack down to end.
        const startIdx = activeStack.indexOf(k);
        for(let i=startIdx; i<activeStack.length; i++) {
             stateMap[activeStack[i]].computed = "#CYCLE";
        }
        // Return error indicator so dependent formulas treat as non-numeric and fail -> #ERR later?
        return NaN; 
     }

     activeStack.push(k);

     try {
         const rawText = stateMap[k].raw || "";

         if (!rawText.startsWith("=")) {
             // Plain text or empty. Display itself (unless empty => "" is displayed as "").
             return String(rawText);
         }

         const exprStr = rawText.slice(1).trim();

         // Tokenize and convert to RPN, then evaluate
         let rpnTokens;
         try {
            rpnTokens = shuntingYard(exprStr);
         } catch(e) {
             return "#ERR"; 
         }

         const operandStack = [];
         for(let token of rpnTokens) {
             if (typeof token === 'number') {
                 operandStack.push(token);
             } else if (token === '#CYCLE' || isNaN(token)) { // Propagated error?
                // If we encounter #ERR or NaN from a dependency, treat as invalid op.
                continue; 
             } else if (typeof token === 'string') {
                 // It's an operator OR cell ref string like "A1".
                 const val = resolveCellRef(token);
                 operandStack.push(val);
             } else { /* ignore */ }
         }

         let resVal;
         try {
            if (operandStack.length !== 1) return "#ERR"; // Syntax error? RPN should produce single value.
            resVal = operandStack[0];

            if (!Number.isFinite(resVal)) {
                return "#ERR";
            } else {
                // Return formatted number string for display, or just the number itself which will be Stringified later?
                // Better keep as Number and convert to string on final set. But spec says displays computed value; plain text also allowed.
                // For formulas result is numeric usually. Let's return Number type so we can differentiate from strings in RPN logic (though tokens are numbers). 
                // If formula returns NaN -> #ERR handled above.
                if(resVal === 0 && stateMap[k].raw !== "") resVal = "0"; // Maybe keep as number? I'll cast to string at end of ensureComputed anyway via String(...).
                return resVal;
            }
         } catch(e) {
             return "#ERR";
         }

     } finally {
         activeStack.pop();
     }
  }

  function resolveCellRef(refKey) {
      // refKey is string like "A1" or token from RPN.

      if (activeStack.includes(refKey)) {
          const startIdx = activeStack.indexOf(refKey);
          for(let i=startIdx; i<activeStack.length; i++) {
              stateMap[activeStack[i]].computed = "#CYCLE";
          }
          return NaN; // Invalid operand to trigger error in caller.
      }

      if (!stateMap.hasOwnProperty(refKey)) {
          // Reference to non-cell -> Error (or treat as 0? Spec says reference to a non-cell shows #ERR)
          // Since we don't have such cells, this could be valid for external refs not present in grid.
          return "#ERR";
      }

      // If already computed and not currently being calculated recursively with stack conflict? 
      // We need current state: if it's part of a cycle (marked #CYCLE) or error (#ERR), we should propagate that value to allow arithmetic failure handling downstream.

      const cellData = stateMap[refKey];

      // If not yet computed in this pass, calculate now recursively
      let val;
      if (!cellData || typeof cellData.computed === 'undefined') {
          val = calc(refKey);
      } else {
          // It has a stored value. But is it valid? 
          // We can trust the stored computed string (which might be "#CYCLE", "#ERR" or number string).
          if(cellData.computed.startsWith("#")) return cellData.computed;

          val = parseFloat(cellData.computed);
      }

      // If recursion returned NaN, it means cycle detection happened inside that branch? 
      // Or maybe error. Return NaN to trigger #ERR propagation in RPN op handling.
      if (isNaN(val) && !isFinite(val)) return "#ERR"; 

      return val;
  }

  function generateCellKeys() {
     const keys = [];
     for(let col of COLS) {
         for(let row=1; row<=10; row++) {
             keys.push(col + row);
         }
     }
     return keys;
  }

  // --- Simple RPN Shunting Yard ---
  function shuntingYard(exprStr) {
      const tokens = [];
      let currentNum = "";

      for(let i=0; i<exprStr.length; i++) {
          const ch = exprStr[i];

          if (ch === ' ') continue; // ignore spaces

          // Check operator precedence: + - * /
          if (/[+\-*/]/.test(ch)) {
              tokens.push(currentNum); currentNum="";
              while(tokens.length > 0 && /^[+\-*\/]$/.test(peekToken())) {
                  const top = peekToken();
                  // Left to right associativity for same prec? 
                  if (precedence(top) >= precedence(ch)) {
                       tokens.push(pop());
                  } else break;
              }
              tokens.push(ch);
          } else if (ch === '(') {
               tokens.push(currentNum); currentNum="";
               tokens.push('(');
          } else if (ch === ')') {
               tokens.push(currentNum); currentNum="";
               while(peekToken() !== '(' && tokens.length > 0) {
                   tokens.pop();
               }
               // Pop '(' but don't add to output. 
               pop(); 
          } else {
              // Number or Cell Ref (e.g., A1). Distinguish by regex: If starts with letter, it's REF? But in RPN we need separate handling for eval later.
              // We can just push the string segment as one token if it is a number OR cell ref? 
              // However numbers are digits; Cell refs start with letters and end with digits. Mixed like "A1" needs to stay together.
              currentNum += ch;
          }
      }
      tokens.push(currentNum);

      let output = [];
      for(let token of tokens) {
          if (token === '') continue;

          // Check number: contains only digits and at most one dot?
          const numStr = String(token).match(/^-?\d+(\.\d+)?$/);
          if(numStr && !isNaN(parseFloat(token))) {
              output.push(parseFloat(token));
          } else if (/[+\-*\/]/.test(String(token)) && token.length===1) {
               // Operator in tokens list? We might have captured it as part of string due to logic above. 
               // Actually our loop pushes operators immediately, so they should be separate tokens pushed directly via `tokens.push(ch)` when ch is op. 
               // But if operator appears after number without space (e.g. "2+3") we push num then pop empty currentNum then op -> token list gets 'num','op'. So fine.

               const op = String(token);
               let prec = 1;
               if(op === '*' || op === '/') prec=2;
               while(output.length > 0 && isOperator(peekToken())) {
                   const topOp = peekToken();
                   // Higher or equal precedence? For left-to-right, pop if >=. 
                   if(precedence(topOp) >= prec) output.push(pop()); else break;
               }
               output.push(op);
          } else if (isOperator(token)) {
              const op = String(token);
               let prec = 1;
               if(op === '*' || op === '/') prec=2;
               while(output.length > 0 && isOperator(peekToken())) {
                   const topOp = peekToken();
                   if(precedence(topOp) >= prec) output.push(pop()); else break;
               }
               output.push(op);
          } else if (isNumber(token)) {
              output.push(parseFloat(String(token)));
          } else {
              // Must be Cell Ref string like "A1" -> push as object or keep string? Keep string for later.
              output.push(String(token));
          }
      }

      return output;

      function peekToken() { return tokens[tokens.length-1]; }
      function pop() { return tokens.pop(); }

      function isOperator(s) { if(!s || typeof s !== 'string') return false; return /^[+\-*\/]$/.test(s); }
      function precedence(op) { return (op==='*' || op==='/')?2:1; }
  }

  // --- API Export ---

  window.sheet = {
      set: function(cellKey, text) {
          if(stateMap.hasOwnProperty(cellKey)) {
              stateMap[cellKey].raw = String(text);
              const inputEl = document.getElementById(cellKey);
              if(inputEl && !inputEl.matches(":focus")) { // Don't override focused edit? Or update UI regardless for consistency.
                  inputEl.value = text; 
              } else {
                   // If focus was there, maybe user is editing and we want to set raw but keep visual as computed after commit?
                   // We'll just update stateMap; the next blur will flush it or if they are typing over...
                   // Simpler: Update input value only if not focused or force update. 
              }
          }
          recalcAll();
      },
      get: function(cellKey) {
          return stateMap[cellKey] ? String(stateMap[cellKey].computed ?? "") : "";
      },
      raw: function(cellKey) {
          return stateMap[cellKey] ? String(stateMap[cellKey].raw ?? "") : "";
      }
  };

  // --- Button Export CSV ---
  document.getElementById('export').addEventListener('click', function() {
     const keys = generateCellKeys();
     let csvContent = "Row,A,B,C,D,E,F,G,H,I,J\n";

     for(let row=1; row<=10; row++) {
         // Build CSV: For each column, get computed value. 
         let lineParts = [];
         for(let col of COLS) {
             const cellId = col + row;
             const val = String(stateMap[cellId] ? stateMap[cellId].computed : "");
             lineParts.push(val); // Escape commas if needed? CSV spec: quote if contains comma. Not strictly required by prompt but safe.
         }
         csvContent += lineParts.join(",") + "\n";
     }

     const area = document.getElementById('csv-output');
     area.value = csvContent;
  });

  // --- Initialization ---

  initGrid();
  recalcAll(); 

})();
</script>
</body>
</html>
